_SENTINEL = object()  # a unique, unforgeable sentinel

def get(d, key, default=_SENTINEL):
    if key in d:
        return d[key]
    if default is _SENTINEL:
        raise KeyError(key)
    return default

def greet(name=None):
    name = name or "stranger"
    return f"Hello, {name}!"

def get_cache_entry(cache, key):
    value = cache.get(key)
    return "MISS" if value is None else value
